CREATE OR REPLACE FUNCTION public.admin_has_permission(p_module text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_super boolean;
  v_disabled boolean;
  v_admin_role uuid;
begin
  select p.role, p.is_super_admin, p.is_disabled, p.admin_role_id
    into v_role, v_super, v_disabled, v_admin_role
  from public.profiles p where p.id = auth.uid();

  if v_role is distinct from 'admin' or coalesce(v_disabled, false) then return false; end if;
  if v_super then return true; end if;
  -- Every admin may read and export student performance.
  if p_module = 'reports' and p_action in ('view', 'export') then return true; end if;
  if v_admin_role is null then return false; end if;
  return exists (
    select 1 from public.admin_role_permissions rp
    where rp.role_id = v_admin_role
      and rp.module = p_module
      and (rp.action = p_action or rp.action = 'manage')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_module()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text;
  v_alt text := case when tg_nargs > 1 then tg_argv[1] else null end;
  v_cols text[] := case when tg_nargs > 2 then string_to_array(tg_argv[2], ',') else '{}'::text[] end
                   || array['updated_at'];
begin
  if auth.uid() is null or public.current_profile_role() is distinct from 'admin' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  v_action := case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'edit' else 'delete' end;

  if public.admin_has_permission(tg_argv[0], v_action) then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'UPDATE' and v_alt is not null
     and public.admin_has_permission(v_alt, 'configure')
     and (to_jsonb(new) - v_cols) = (to_jsonb(old) - v_cols) then
    return new;
  end if;

  raise exception 'Your admin account does not have permission to % in %.', v_action, tg_argv[0]
    using errcode = '42501';
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_feature_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and not public.feature_available(tg_argv[0]) then
    raise exception 'This feature is turned off right now.' using errcode = '42501';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.login_allowed_for(p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role     text;
  v_branch   uuid;
  v_disabled boolean;
  v_open     boolean;   -- allow_unassigned
  v_dept     boolean;
  v_class    boolean;
begin
  select p.role, p.branch_id, p.is_disabled into v_role, v_branch, v_disabled
  from public.profiles p
  where p.id = p_user;

  if v_role is null then return false; end if;      -- unknown user
  if coalesce(v_disabled, false) then return false; end if;
  if v_role <> 'student' then return true; end if;  -- staff are never gated

  select coalesce(a.allow_unassigned, true) into v_open
  from public.access_settings a where a.id;
  v_open := coalesce(v_open, true);

  -- Department gate.
  if not public.department_login_restricted() then
    v_dept := true;
  elsif v_branch is null then
    v_dept := v_open;
  else
    v_dept := exists (
      select 1 from public.branches b
      where b.id = v_branch and b.is_active and b.login_enabled
    );
  end if;

  -- Class gate.
  if not public.class_login_restricted() then
    v_class := true;
  elsif not exists (
    select 1 from public.class_members cm
    join public.classes c on c.id = cm.class_id
    where cm.student_id = p_user and c.status = 'active'
  ) then
    v_class := v_open;
  else
    v_class := exists (
      select 1 from public.class_members cm
      join public.classes c on c.id = cm.class_id
      where cm.student_id = p_user
        and c.status = 'active'
        and c.login_enabled
    );
  end if;

  return v_dept and v_class;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_guard_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_role text;
  v_super boolean;
begin
  if auth.uid() is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  v_caller_role := public.current_profile_role();
  v_super := public.is_super_admin();

  if tg_op = 'DELETE' then
    if old.id = auth.uid() then
      raise exception 'You cannot delete your own account.' using errcode = '42501';
    end if;
    if not v_super and (old.role = 'admin' or not public.admin_has_permission('users', 'delete')) then
      raise exception 'You do not have permission to delete this account.' using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if not v_super and (new.role = 'admin' or new.is_super_admin or new.admin_role_id is not null) then
      raise exception 'Only a super admin can create admin accounts.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE ------------------------------------------------------------------

  -- Nobody but a super admin grants or removes admin powers.
  if not v_super then
    if new.is_super_admin is distinct from old.is_super_admin
       or new.admin_role_id is distinct from old.admin_role_id
       or (new.role = 'admin') is distinct from (old.role = 'admin') then
      raise exception 'Only a super admin can change admin privileges.' using errcode = '42501';
    end if;
  end if;

  -- The disable switch is an administrator's decision: a disabled student must
  -- not be able to switch themselves back on through profiles_update_self, and
  -- faculty (profiles_staff_update) must not be able to flip it either.
  if new.is_disabled is distinct from old.is_disabled then
    if v_caller_role is distinct from 'admin' then
      raise exception 'Only an administrator can enable or disable accounts.' using errcode = '42501';
    end if;
    if old.id = auth.uid() then
      raise exception 'You cannot disable your own account.' using errcode = '42501';
    end if;
  end if;

  -- A plain admin may edit their own row (name) and — with users.edit — student
  -- and faculty rows. Other admins' rows belong to the super admin.
  if v_caller_role = 'admin' and not v_super and old.id <> auth.uid() then
    if old.role = 'admin' then
      raise exception 'Only a super admin can modify another admin account.' using errcode = '42501';
    end if;
    if not public.admin_has_permission('users', 'edit') then
      raise exception 'Your admin account does not have permission to edit users.' using errcode = '42501';
    end if;
  end if;

  if new.is_super_admin and new.role <> 'admin' then
    raise exception 'A super admin must hold the admin role.' using errcode = '23514';
  end if;

  -- A super admin cannot lock themselves out; another super admin can.
  if old.id = auth.uid() and old.is_super_admin
     and (not new.is_super_admin or new.role <> 'admin' or new.is_disabled) then
    raise exception 'You cannot remove your own super admin access.' using errcode = '42501';
  end if;

  if new.is_disabled and not old.is_disabled then
    new.disabled_at := now();
  elsif not new.is_disabled then
    new.disabled_at := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_prevent_academic_self_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    return new;
  end if;
  if public.current_profile_role() = 'admin' then
    return new;
  end if;
  if new.roll_number is distinct from old.roll_number
     or new.year is distinct from old.year
     or new.branch_id is distinct from old.branch_id
     or new.section_id is distinct from old.section_id
     or new.institute_id is distinct from old.institute_id then
    raise exception 'Only admins can change roll number, year, branch, section or institute';
  end if;
  if new.username is distinct from old.username
     or new.email is distinct from old.email then
    raise exception 'Only admins can change username or email';
  end if;
  return new;
end;
$function$
